// TestJSXDocExamples renders the doc examples, statically and in a live
// session: each chain encodes, its handlers are ones an on… attribute
// takes, and its branches are well formed.
//
//line jsx_test.vuka:409
func TestJSXDocExamples(t *testing.T) {
	got, err := ui.String(context.Background(), ui.HTML(`{&Docs{}}`, &Docs{}))
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{`"else_if"`, `"exec"`, `"call"`, `"throttle"`, `"debounce"`, `"set_value"`, `"busy"`, `"attr"`, `"and"`, `"some"`} {
		if !strings.Contains(got, html.EscapeString(want)) {
			t.Errorf("no %s rendered", want)
		}
	}
	c, err := livetest.Join(live.NewSession(context.Background(), func(context.Context) ui.Node { return ui.HTML(`{&Docs{}}`, &Docs{}) }), 2)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{`"keep":true`, `"timeout":3000`, `"on_ok"`, `"on_error"`, `"value":0`} {
		if !strings.Contains(c.HTML(), want) && !strings.Contains(c.HTML(), html.EscapeString(want)) {
			t.Errorf("no %s in the live page", want)
		}
	}
}

